package com.travbook.journeys.adapter.out.commerce;
import com.travbook.journeys.application.port.out.*;
import com.travbook.journeys.domain.model.Care.*;
import com.travbook.payments.application.port.in.*;
import com.travbook.payments.domain.model.Payment;
import java.util.*;
public final class JourneyCareEffectAdapter implements JourneyCareEffects {
 private final JourneyCareSupplier supplier;private final PaymentOperations payments;private final PaymentRefunds refunds;private final JourneySupplier current;private final JourneyStore store;private final JourneyCareStore care;
 public JourneyCareEffectAdapter(JourneyCareSupplier s,PaymentOperations p,PaymentRefunds r,JourneySupplier current,JourneyStore store,JourneyCareStore care){this.care=care;supplier=s;payments=p;refunds=r;this.current=current;this.store=store;}
 public void validate(Action a){var b=a.booking();var c=current.current(b.id()).orElseThrow();var p=payments.current(b.id()).orElseThrow();if(!c.status().equals("CONFIRMED")||!c.mode().equals("MOCK")||c.confirmedComponents()!=b.quote().selection().components().size()||!c.bookingId().equals(b.id())||!c.resource().equals(b.quote().selection().supplier()+":"+b.quote().selection().resource())||!p.paymentId().equals(b.id())||!p.mode().equals("MOCK")||!p.currency().equals("INR")||!p.owner().equals(b.quote().owner())||p.state()!=Payment.State.CAPTURED||p.amount().compareTo(store.terms(b.quote().id()).firstAmount().decimal())!=0||p.committedRefunds().signum()!=0)throw new IllegalStateException("Reservation or source funding needs reconciliation");}
 public boolean recoveryEvidence(Action a){var receipt=lookup(a).orElse(null);if(receipt==null)return false;if(a.step()==Phase.CANCEL){var c=current.current(a.booking().id()).orElse(null);var state=care.summary(a.booking().quote().owner(),a.booking().id());long remaining=state.activeComponentIds().stream().filter(id->!a.componentIds().contains(id)).count();return c!=null&&c.mode().equals("MOCK")&&c.status().equals(remaining==0?"CANCELLED":"CONFIRMED")&&c.confirmedComponents()==remaining&&(a.booking().quote().selection().request().kind()!=com.travbook.journeys.domain.model.Journey.Kind.BUS||c.activeSeats()==remaining);}var id=a.type()==Type.BALANCE?a.id():a.currentRefund().paymentId();var p=payments.current(id).orElse(null);if(p==null||!p.owner().equals(a.booking().quote().owner())||!p.mode().equals("MOCK")||!p.currency().equals("INR"))return false;return switch(a.step()){case AUTHORIZE->p.state()==(receipt.accepted()?Payment.State.AUTHORIZED:Payment.State.DECLINED)&&p.committedRefunds().signum()==0;case CAPTURE->p.state()==(receipt.accepted()?Payment.State.CAPTURED:Payment.State.AUTHORIZED)&&p.committedRefunds().signum()==0;case VOID->p.state()==Payment.State.VOIDED;case REFUND,REFUND_STATUS->p.state()==Payment.State.CAPTURED&&p.committedRefunds().compareTo(a.currentRefund().amount().decimal())>=0;default->false;};}
 public Optional<Result> lookup(Action a){return switch(a.step()){
  case CANCEL->supplier.lookup(a.operation("cancel")).map(r->{if(!r.operationId().equals(a.operation("cancel"))||!r.bookingId().equals(a.booking().id())||!r.components().equals(a.componentIds())||!r.fingerprint().equals(a.booking().supplierFingerprint())||!r.mode().equals("MOCK")||!r.reference().equals("MOCK-JOURNEY-"+a.booking().id()))throw new IllegalStateException("Cancellation receipt mismatch");return new Result(r.accepted(),true,r.reference());});
  case AUTHORIZE,CAPTURE,VOID->payments.lookup(a.operation(a.step().name())).map(r->{String state=a.step()==Phase.AUTHORIZE?"AUTHORIZED":a.step()==Phase.CAPTURE?"CAPTURED":"VOIDED";if(!r.operationId().equals(a.operation(a.step().name()))||!r.paymentId().equals(a.id())||!r.mode().equals("MOCK")||!r.currency().equals("INR")||r.amount().compareTo(a.amount().decimal())!=0||r.accepted()!=r.state().name().equals(state)||!r.accepted()&&!(a.step()==Phase.AUTHORIZE&&r.state()==Payment.State.DECLINED||a.step()==Phase.CAPTURE&&r.state()==Payment.State.AUTHORIZED)||!r.reference().equals("MOCK-PAY-"+a.id()))throw new IllegalStateException("Balance receipt mismatch");return new Result(r.accepted(),true,r.reference());});
  case REFUND,REFUND_STATUS->refunds.lookup(a.operation("refund:"+a.refundIndex())).map(r->{var part=a.currentRefund();if(!r.operationId().equals(a.operation("refund:"+a.refundIndex()))||!r.paymentId().equals(part.paymentId())||r.amount().compareTo(part.amount().decimal())!=0||!r.currency().equals("INR")||!r.mode().equals("MOCK")||r.reference()==null||!r.reference().startsWith("MOCK-REFUND-"))throw new IllegalStateException("Care refund binding mismatch");return new Result(true,r.completed(),r.reference());});default->Optional.empty();};}
 public Result execute(Action a){switch(a.step()){
  case CANCEL->supplier.cancel(a);
  case AUTHORIZE,CAPTURE,VOID->payments.execute(new PaymentOperations.Command(a.operation(a.step().name()),a.id(),a.booking().quote().owner(),Payment.Operation.valueOf(a.step().name()),a.amount().decimal(),"INR",a.deadline(),a.simulateDecline()&&a.step()==Phase.AUTHORIZE));
  case REFUND->{var part=a.currentRefund();refunds.submit(new PaymentRefunds.Command(a.operation("refund:"+a.refundIndex()),part.paymentId(),a.booking().quote().owner(),a.id(),part.amount().decimal(),"INR",a.simulateDelay(),a.correlationId(),a.id()));}
  default->throw new IllegalStateException("No known provider receipt");}
  if(a.responseLoss())throw new IllegalStateException("Simulated response loss after committed effect");return lookup(a).orElseThrow();}
}
